entries[1257796] = { ["name"] = "Silvermoon Parade", ["text"] = "2 sec cast 2\nReagents:\nLynxfish (4), Tavern Fixings , Arcane Wyrmfish (4), Cooking Spirits , Practically Pork (10), Petrified Root\nOptional Reagents:\nSecret Ingredient (#480)\nRecipe for 2 servings. Actual number of servings will vary based on cooking skill.\nProfession Trainer:\nMidnight Cooking (85)\nCost:\n200\n\nSilvermoon Parade\n\nUse: Place a Silvermoon Parade for all players to enjoy!\n\nRestores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n\nWell Fed\nIf you spend at least 10 seconds eating, you will become Well Fed gaining 98 Stamina and 50 primary stat for 1 hour.\n90" }
entries[1257798] = { ["name"] = "Trap: Void Sphere", ["text"] = "Instant 8 sec cooldown\nCast Time: 2.5 seconds.\nTrap Cooldown: 8 seconds.\nCan be cast while moving.\n\nCreates a Void Sphere that persists for 30 sec. The sphere behaves differently for Hiders and Seekers.\n\nHiders who make contact with the sphere are propelled forwards up to 30 yards.\n\nSeekers who make contact with the sphere are repelled backwards up to 20 yards.\n\nDon't worry--the cold emptiness of the void lasts for but a moment. Soon, your guts will be be wrenched in one direction or another, and it will all be over before you know it." }
